OLD_URL = "https://www2.gov.bc.ca/assets/gov/environment/climate-change/ind/obps/guidance/bc_obps_guidance.pdf"
NEW_URL = "https://www2.gov.bc.ca/assets/gov/environment/climate-change/ind/obps/guidance/bc_obps_program_and_reporting_guidance.pdf"

TEMPLATE_NAMES = [
    'BORO ID Application Approved',
    'Opt-in And BORO ID Application Approved',
]


def update_guidance_document_link(apps, schema_editor):
    EmailNotificationTemplate = apps.get_model('common', 'EmailNotificationTemplate')
    for template in EmailNotificationTemplate.objects.filter(name__in=TEMPLATE_NAMES):
        template.body = template.body.replace(OLD_URL, NEW_URL)
        template.save()


